+          text: humanize(modifier.name),
+          active: active?.contains(modifier.name) ?? false,
+          onAction: () => {
+            mutateClasses(
+              editor,
+              (element) => element.classList.toggle(modifier.name),
+              model,
+            );
+          },
+        })),
+    });
+  }
+  return items;
+}
+
+function menuItems(editor: Editor, model: readonly CssDocEntry[]): Ui.Menu.MenuItemSpec[] {
+  const context = selectedContext(editor, model);
+  if (!context) return [];
+  const applicable = getApplicableModifiers(context.entry.name, model);
+  const componentItems = groupedItems(
+    editor,
+    model,
+    applicable.filter(({ scope }) => scope === "component"),
+  );
+  const utilities = Map.groupBy(
+    applicable.filter(({ scope }) => scope === "utility"),
